"""Metadatos y composición (roster) de cada comando, transcritos de la página
"Selección de comando" de cada PDF."""
from itertools import product

UNIVERSAL = ['deposito-municion', 'alambre-puas', 'aparato-comunicaciones', 'minas', 'barricadas-ligeras',
             'barricada-pesada', 'escaleras', 'granadas-especiales', 'granadas-explosivas', 'carga-demolicion', 'barricada-portatil']
EQUIP = {'slots': 4, 'universal': UNIVERSAL}

def cap(s): return s[:1].upper() + s[1:]
def lo(*opts):
    """Opciones de armamento -> loadouts {label, w[]}"""
    return [{'label': cap(o), 'w': [{'n': cap(x.strip())} for x in o.split(';')]} for o in opts]
def each(*cats):
    """Una opción de cada categoría (producto cartesiano)."""
    return [cap('; '.join(x.lower() if i else x for i, x in enumerate(p))) for p in product(*cats)]
def uimg(folder, m, ext='jpg'):
    return {k: f'imagenes/{folder}/{v}.{ext}' for k, v in m.items()}

